WITH sales_month AS (SELECT cs_call_center_sk, cs_sold_date_sk AS month_sk, SUM(cs_net_paid) AS month_sales_net FROM catalog_sales GROUP BY cs_call_center_sk, cs_sold_date_sk), returns_month AS (SELECT cr_call_center_sk, cr_returned_date_sk AS month_sk, SUM(cr_net_loss) AS month_returns_loss FROM catalog_returns GROUP BY cr_call_center_sk, cr_returned_date_sk), combined_month AS (SELECT s.cs_call_center_sk AS call_center_sk, s.month_sk, s.month_sales_net, COALESCE(r.month_returns_loss, 0) AS month_returns_loss, (s.month_sales_net - COALESCE(r.month_returns_loss, 0)) AS net_profit FROM sales_month s LEFT JOIN returns_month r ON s.cs_call_center_sk = r.cr_call_center_sk AND s.month_sk = r.month_sk) SELECT cc.cc_call_center_id, cc.cc_name, cm.month_sk, cm.month_sales_net, cm.month_returns_loss, cm.net_profit, CASE WHEN cm.net_profit >= 0 THEN 'Profit' ELSE 'Loss' END AS profit_status, SUM(cm.net_profit) OVER (PARTITION BY cc.cc_call_center_sk ORDER BY cm.month_sk ROWS UNBOUNDED PRECEDING) AS cumulative_net_profit, AVG(cm.net_profit) OVER (PARTITION BY cc.cc_call_center_sk ORDER BY cm.month_sk ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS rolling_avg_4_months, cm.net_profit - LAG(cm.net_profit) OVER (PARTITION BY cc.cc_call_center_sk ORDER BY cm.month_sk) AS month_over_month_change, RANK() OVER (PARTITION BY cc.cc_state ORDER BY cm.net_profit DESC) AS state_rank_by_latest_month FROM combined_month cm JOIN call_center cc ON cm.call_center_sk = cc.cc_call_center_sk WHERE cm.month_sk IS NOT NULL ORDER BY cc.cc_call_center_id, cm.month_sk
